Actionscript.script:
this._x = 150;
this._y = 20;

function 组装副本任务(对象)
{
	var taskData = _root.getTaskData(对象.NPC任务_任务_关卡路径);
	// 副本任务已迁 web（task 面板副本 tab）：通缉单直发 openWebDungeon。
	// 旧 Symbol 1873(_root.委托任务界面) fallback 已退役删除（主 FLA 已删该元件）。
	if (_root.gameCommands.openWebDungeon != undefined)
	{
		_root.gameCommands.openWebDungeon({taskId: taskData.id});
	}
}

function 买一杯酒(对象)
{
	if (对象.对话完毕)
	{
		return;
	}
	if (_root.金钱 >= 对象.价格)
	{
		var assetContext = {source:"tavern_purchase", reason:"buy_drink", mergeScope:"operation"};
		_root.金钱 -= 对象.价格;
		_root.记录玩家货币变化(
			-Number(对象.价格), 0, assetContext);
		if (_root.存档系统 != undefined) _root.存档系统.dirtyMark = true;
		_root.SetDialogue(对象.对话[对象.对话index], true);
		对象.对话index += 1;
		对象.显示文字 = "$" + 对象.价格 + " (" + 对象.对话index + "/" + 对象.对话.length + ")";
		if (对象.对话index >= 对象.对话.length)
		{
			对象.显示文字 = "SOLD OUT";
			对象.对话完毕 = true;
			对象.对话完毕回调函数();
		}
	}
	else
	{
		_root.发布消息("金钱不足！");
	}
}

当前页数 = 1;
stop();

on(release){
   _parent.当前页数 += 1;
   _parent.nextFrame();
}
onClipEvent(load){
   显示文字 = _root.获得翻译("下一页");
}
on(rollOver){
   _root.注释(150,this.显示文字);
	this._xscale = 120;// 将影片剪辑的水平缩放设置为108%
	this._yscale = 108;// 将影片剪辑的垂直缩放设置为100%
	this._rotation += 10; // 将元件的旋转角度增加10度
	this._x -= 15; // 将元件的水平位置向左偏移15个像素
	this._y -= 15; // 将元件的水平位置向上偏移15个像素
	//当前层级 = this.getDepth();// 保存当前元件的层级值
	//this.swapDepths(_root.getNextHighestDepth()); // 将当前影片剪辑置于最顶层
}
on(rollOut){
   _root.注释结束();
	this._xscale = 108;// 将影片剪辑的水平缩放设置为108%
	this._yscale = 100;// 将影片剪辑的垂直缩放设置为100%
