onClipEvent (load) {
	价格 = 50;
	显示文字 = "$" + 价格;
	对话index = 0;
	对话完毕 = true;
	var self = this;
	org.flashNight.neur.Server.DataQueryService.query(
		"npc_dialogue",
		{key: "酒泡氤氲-啤酒", taskProgress: _root.主线任务进度},
		function(response:Object):Void {
			if (response.success && response.result != null && response.result.length > 0)
			{
				self.对话 = response.result;
				self.对话完毕 = false;
			}
			else
			{
				self.显示文字 = "补货中";
			}
		}
	);
	function 对话完毕回调函数(){
		if(_root.收集品栏.情报.getValue("酒泡氤氲") == 0){
			_root.收集品栏.情报.add("酒泡氤氲",1);
			_root.记录玩家物资变化(
				"gain", "intel", "酒泡氤氲", 1,
				{source:"tavern_purchase", reason:"beer_intelligence"});
			_root.最上层发布文字提示("已将对话整理为新的情报页面");
		}
	}
}
on (rollOver) {
	gotoAndStop(2);
	this.swapDepths(_parent.getNextHighestDepth());
	_root.注释(200,"点一杯啤酒");
}
on (rollOut) {
	gotoAndStop(1);
	_root.注释结束();
}
on (release) {
	_parent.买一杯酒(this);
}

onClipEvent (load) {
	价格 = 200;
	显示文字 = "$" + 价格;
	对话index = 0;
	对话完毕 = true;
	if (_root.主线任务进度 < 23)
	{
		显示文字 = "补货中"
	}
	else
	{
		var self = this;
		org.flashNight.neur.Server.DataQueryService.query(
			"npc_dialogue",
			{key: "酒泡氤氲-鸡尾酒", taskProgress: _root.主线任务进度},
			function(response:Object):Void {
				if (response.success && response.result != null && response.result.length > 0)
				{
					self.对话 = response.result;
					self.对话完毕 = false;
				}
				else
				{
					self.显示文字 = "补货中";
				}
			}
		);
	}
	function 对话完毕回调函数(){
		if(_root.收集品栏.情报.getValue("酒泡氤氲") == 1){
			_root.收集品栏.情报.addValue("酒泡氤氲",1);
			_root.记录玩家物资变化(
				"gain", "intel", "酒泡氤氲", 1,
				{source:"tavern_purchase", reason:"cocktail_intelligence"});
			_root.最上层发布文字提示("已将对话整理为新的情报页面");
		}
	}
}
